    private static String phase="input";private static int denials;
    private static String site(Throwable failure){
        List<String> frames=new ArrayList<String>();for(StackTraceElement frame:failure.getStackTrace())if(frame.getClassName().startsWith("com.devclaw.botcontrol.")&&frames.size()<4)frames.add(frame.getClassName().substring("com.devclaw.botcontrol.".length())+"."+frame.getMethodName()+":"+frame.getLineNumber());return String.join(",",frames);
    }
    private static boolean same(JsonNode a,JsonNode b)throws Exception{return Arrays.equals(JSON.writeValueAsBytes(a),JSON.writeValueAsBytes(b));}
    private static void check(boolean value){if(!value)throw new IllegalStateException();}
    private static void denied(ErrorCode code,Runnable work){try{work.run();throw new IllegalStateException();}catch(ApplicationFault f){if(f.code!=code)throw new IllegalStateException("EXPECTED_"+code+"_ACTUAL_"+f.code);denials++;}}
    private static String id(JsonNode n,String key){return GroupMemoryValues.id(n.path(key).textValue());}
    private static Instant expiry(){return Instant.ofEpochMilli(System.currentTimeMillis()+600000);}
    private static Task task(HikariDataSource source,String id)throws Exception{try(Connection c=source.getConnection()){c.setAutoCommit(false);Task t=new JdbcTaskStore(c,"A").task(id);c.rollback();return t;}}
    private static long count(HikariDataSource source,String table)throws Exception{try(Connection c=source.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM "+table)){p.setQueryTimeout(2);try(ResultSet r=p.executeQuery()){check(r.next());return r.getLong(1);}}}
    private static void sql(HikariDataSource source,String sql,Object... args)throws Exception{try(Connection c=source.getConnection();PreparedStatement p=c.prepareStatement(sql)){c.setAutoCommit(false);p.setQueryTimeout(2);for(int i=0;i<args.length;i++){if(args[i] instanceof byte[])p.setBytes(i+1,(byte[])args[i]);else p.setObject(i+1,args[i]);}check(p.executeUpdate()==1);c.commit();}}
    private static byte[] bytes(HikariDataSource source,String sql,String id)throws Exception{try(Connection c=source.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,id);p.setQueryTimeout(2);try(ResultSet r=p.executeQuery()){check(r.next());byte[] b=r.getBytes(1);check(!r.next());return b;}}}
    private static CreateTaskRequest request(String group,String command){CreateTaskRequest t=new CreateTaskRequest();t.commandId=command;t.groupId=group;t.title="文本成果";t.goal="保留业务规则，明确边界";t.inputArtifactVersions=Collections.emptyList();return t;}
    private static Task create(HikariDataSource source,RuntimeNodeDatabaseProbe.Policy p,String group,String command){ApplicationResponse r=new TaskApplication(source,p,TransactionObserver.NONE).execute(Operation.CREATE_TASK,BUSINESS,null,null,null,JdbcApplicationStore.json(request(group,command)));check(r.status==201);return B.readResponse("createTask",201,r.body(),TaskResult.class).task;}
    private static Run enqueue(RequirementRunApplication runs,Task task,String bot,String command){return runs.claimRequirementRun(NODE,runs.enqueueRequirement(BUSINESS,command,task.id,bot,task.version,expiry()).runId);}
    private static Run complete(RequirementRunApplication runs,Task task,String bot,String command,String text){
        String history=command.startsWith("history-run-")?command.substring("history-run-".length()):null;
        if(history!=null)phase="summary-"+history+"-enqueue";
        String runId=runs.enqueueRequirement(BUSINESS,command,task.id,bot,task.version,expiry()).runId;
        if(history!=null)phase="summary-"+history+"-claim";Run run=runs.claimRequirementRun(NODE,runId);
        if(history!=null)phase="summary-"+history+"-start";runs.startRequirementRun(NODE,run.id,run.attemptId,run.leaseId,run.fence);
        if(history!=null)phase="summary-"+history+"-settle";runs.settleRequirementRun(NODE,run.id,run.attemptId,run.leaseId,run.fence,"succeeded",text);return run;
    }
    private static String facts(HikariDataSource source)throws Exception{
        MessageDigest digest=MessageDigest.getInstance("SHA-256");List<String> tables=new ArrayList<String>(DatabaseReadiness.TABLES);tables.addAll(DatabaseReadiness.EXPERT_TABLES);
        try(Connection c=source.getConnection();DataOutputStream out=new DataOutputStream(new DigestOutputStream(new OutputStream(){public void write(int b){}},digest))){c.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);c.setAutoCommit(false);
            for(String table:tables){out.writeUTF(table);List<String> rows=new ArrayList<String>();try(PreparedStatement p=c.prepareStatement("SELECT * FROM "+table+(table.equals("bot_schema_history")?" WHERE CAST(version AS UNSIGNED)<=7":""))){p.setQueryTimeout(2);try(ResultSet r=p.executeQuery()){while(r.next()){ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream row=new DataOutputStream(b);for(int i=1;i<=r.getMetaData().getColumnCount();i++){if(Arrays.asList("delivery_version_id","execution_profile","context_digest").contains(r.getMetaData().getColumnName(i)))continue;byte[] v=r.getBytes(i);row.writeInt(v==null?-1:v.length);if(v!=null)row.write(v);}rows.add(Base64.getEncoder().encodeToString(b.toByteArray()));}}}Collections.sort(rows);for(String row:rows)out.writeUTF(row);out.writeBoolean(false);}c.rollback();}
        StringBuilder hex=new StringBuilder();for(byte b:digest.digest())hex.append(String.format(Locale.ROOT,"%02x",b&255));return hex.toString();
    }
    private static ObjectNode seedV7(HikariDataSource source)throws Exception{
        check(MigrationRunner.configuration(source).target("7").load().migrate().migrationsExecuted==7);RuntimeNodeDatabaseProbe.Policy p=new RuntimeNodeDatabaseProbe.Policy();ObjectNode ids=RuntimeNodeDatabaseProbe.seed(source,p);RuntimeNodeApplication nodes=new RuntimeNodeApplication(source,p,p,TransactionObserver.NONE);nodes.observeDesktopNode(NODE,true,Collections.singleton(Capability.REQUIREMENTS_ANALYZE));nodes.authorizeRequirementNode(OWNER,id(ids,"group"),"node","view",0,expiry());ObjectNode old=LegacyMemoryRunFixture.create(source,nodes,id(ids,"task"),id(ids,"bot"),"v7-result",expiry(),"succeeded");ObjectNode result=JSON.createObjectNode().put("facts",facts(source));result.set("ids",ids);result.put("runId",old.path("id").textValue());return result;
    }
    private static ObjectNode verifyV7(HikariDataSource source,JsonNode fixture)throws Exception{check(fixture.path("facts").asText().equals(facts(source)));RuntimeNodeDatabaseProbe.Policy p=new RuntimeNodeDatabaseProbe.Policy();RequirementRunApplication runs=new RequirementRunApplication(source,p,p,TransactionObserver.NONE);check(runs.getRequirementResult(BUSINESS,id(fixture,"runId")).text.equals("V5_PERSISTED_RESULT"));for(String table:DatabaseReadiness.DELIVERY_TABLES)check(count(source,table)==0);return JSON.createObjectNode().put("oldFactsUnchanged",true).put("oldResultReadable",true).put("noAutomaticPublication",true);}
