        phase="task-event-versions";try(Connection c=source.getConnection();PreparedStatement q=c.prepareStatement("SELECT target_version FROM mutation_outbox WHERE space_id='A' AND target_type='task' AND target_id=? ORDER BY task_seq")){q.setQueryTimeout(2);q.setString(1,original.id);try(ResultSet r=q.executeQuery()){for(int i=1;i<=5;i++)check(r.next()&&r.getLong(1)==i);check(!r.next());}}
