    public static void main(String[] args){try{check(args.length==1&&Arrays.asList("seed-v7","verify-v7","exercise").contains(args[0]));ByteArrayOutputStream bytes=new ByteArrayOutputStream();for(int b;(b=System.in.read())!=-1;){check(bytes.size()<131072);bytes.write(b);}JsonNode input=JSON.readTree(bytes.toByteArray());LocalDatabaseConfig config=LocalDatabaseConfig.fromTrustedLauncher(new ByteArrayInputStream(JSON.writeValueAsBytes(input.get("db"))));try(HikariDataSource source=config.openPool()){DatabaseReadiness.requireConnection(source);ObjectNode result;if(args[0].equals("seed-v7"))result=seedV7(source);else{DatabaseReadiness.requireReady(source);result=args[0].equals("verify-v7")?verifyV7(source,input.path("fixture")):exercise(source);}result.put("status","verified").put("case",args[0]);System.out.println(JSON.writeValueAsString(result));}}
        catch(Throwable failure){String reason=failure instanceof IllegalStateException&&failure.getMessage()!=null&&failure.getMessage().matches("EXPECTED_[A-Z_]+_ACTUAL_[A-Z_]+")?failure.getMessage():failure instanceof ApplicationFault?((ApplicationFault)failure).code.wire():"ASSERTION";System.out.println("{\"status\":\"failed\",\"phase\":\""+phase+"\",\"reason\":\""+reason+"\",\"site\":\""+site(failure)+"\"}");System.exit(1);}}
